VALUES (51300, 'tt0120125', NULL, 'The Barber of Siberia', 'Сибирский цирюльник', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/6sAm5HWkhjWo7xI0nZjeJTru6mP.jpg', 'https://image.tmdb.org/t/p/original/pKZ9kLAxcXgv9JkE6zf3mNl2a1d.jpg', 'Douglas is a foreign entrepreneur, who ventures to Russia in 1885 with dreams of selling a new, experimental steam-driven timber harvester in the wilds of Siberia. Jane is his assistant. On her travels, she meets two men who would change her life forever: a handsome young cadet Andrej Tolstoy with whom she shares a fondness for opera, and the powerful General Radlov who is entranced by her beauty and wants to marry her.', NULL, NULL, 1.5419, 7.109, 0, 10.52, '2026-11-21 21:03:36', '2026-11-21 21:03:36')
