VALUES (16716, 'tt0216621', NULL, 'A Christmas Carol', 'A Christmas Carol', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/oi1NcVDXlFEsdpLp37BJmFbVlg9.jpg', 'https://image.tmdb.org/t/p/original/mgnY0zuFeYXllJ7qr6zDMCe7hA0.jpg', 'Miser Ebenezer Scrooge is awakened on Christmas Eve by spirits who reveal to him his own miserable existence, what opportunities he wasted in his youth, his current cruelties, and the dire fate that awaits him if he does not change his ways. Scrooge is faced with his own story of growing bitterness and meanness, and must decide what his own future will hold: death or redemption.', NULL, NULL, 5.0718, 7.0, 0, 10.02, '2026-11-21 21:03:36', '2026-11-21 21:03:36')
