VALUES (50541, 'tt0077716', NULL, 'Ice Castles', 'Ice Castles', 'movie', 1978, 'https://image.tmdb.org/t/p/w500/5iS3EJD286IYkJ83L5pEVoNF3xn.jpg', 'https://image.tmdb.org/t/p/original/dBdX0I8QNNhTFxZbMgPQQQdVMTl.jpg', 'Alexis is on top of the world until a tragic accident dashes her hopes and dreams of becoming a world-class figure skater. Only with the help of those who love her can she prove to the world — and herself — that she still has the potential to realize her dreams.', NULL, NULL, 1.4239, 7.4, 0, 10.01, '2026-11-21 21:03:36', '2026-11-21 21:03:36')
