VALUES (80536, 'tt0400900', NULL, 'Twelve Months', '世界名作童話　森は生きている', 'movie', 1980, 'https://image.tmdb.org/t/p/w500/iHO2YGaeBtMD1LMRdoSwNy9ibkj.jpg', 'https://image.tmdb.org/t/p/original/aOZVtH8y1cfc4VssWr8GyN3sVd0.jpg', 'A young queen requests a bouquet of snowdrop flowers for New Year''s Day in exchange for a reward. One greedy woman sends her stepdaughter, whom she does not like, to look for the flowers in a cold forest, knowing the task will be impossible for her. The girl almost freezes to death in the forest, but she is rescued by the spirits of the Twelve Months, who create spring around her. The girl is able to deliver the bouquet to the queen, but others want a share of the reward.', NULL, NULL, 1.7228, 6.9, 0, 9.04, '2026-11-21 21:03:36', '2026-11-21 21:03:36')
