VALUES (57389, 'tt1646975', NULL, 'The Four Times', 'Le quattro volte', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/hCgtAYG53uRdvET4O482paUGMuK.jpg', 'https://image.tmdb.org/t/p/original/rCUI25z0DwcMVBMfZ5MOmMWazkG.jpg', 'An old shepherd lives his last days in a quiet medieval village perched high on the hills of Calabria, at the southernmost tip of Italy. He herds goats under skies that most villagers have deserted long ago. He is sick, and believes to find his medicine in the dust he collects on the church floor, which he drinks in his water every day.', NULL, NULL, 0.6439, 7.464, 0, 10.01, '2026-11-21 21:03:36', '2026-11-21 21:03:36')
