VALUES (42006, 'tt0093206', NULL, 'Red Sorghum', '红高粱', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/2CP2eazEBKJ3njm4HM63pMfs5tW.jpg', 'https://image.tmdb.org/t/p/original/4bjVA2NrkrdNPPpKUt7eR2P3xlf.jpg', 'An old leper who owned a remote sorghum winery dies. Jiu''er, the wife bought by the leper, and her lover, identified only as "my Grandpa" by the narrator, take over the winery and set up an idealized quasi-matriarchal community headed by Jiu''er. When the Japanese invaders subject the area to their rule and cut down the sorghum to make way for a road, the community rises up and resists as the sorghum grows anew.', NULL, NULL, 2.672, 7.4, 0, 10.51, '2026-11-21 21:03:36', '2026-11-21 21:03:36')
