VALUES (NULL, NULL, 481, 'Silent Hill 2', 'Silent Hill 2', 'game', 2001, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2vyg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4kdv.jpg', 'The second entry in the Silent Hill franchise, Silent Hill 2 is a narrative-focused third-person psychological survival horror game with emphasis on combat, exploration and puzzle-solving elements which follows James Sunderland, a man who receives a letter, seemingly sent by his three-years-deceased wife Mary, in which he is beckoned to the fog-ridden town of Silent Hill at the same time as numerous other people troubled by their past.', 'https://www.igdb.com/games/silent-hill-2', '["PlayStation 2"]', NULL, 9.1, 0, 1.05, '2026-11-21 21:03:36', '2026-11-21 21:03:36')
