VALUES (739547, 'tt10442352', NULL, 'Thelma the Unicorn', 'Thelma the Unicorn', 'movie', 2024, 'https://image.tmdb.org/t/p/w500/yutiEZ7taGDNau2jGjKIdDwQpDw.jpg', 'https://image.tmdb.org/t/p/original/3r9aPVVNuCXNOFFXsL03abZs9xF.jpg', 'Thelma dreams of being a glamorous unicorn. Then in a rare pink and glitter-filled moment of fate, Thelma''s wish comes true. She rises to instant international stardom, but at an unexpected cost. After a while, Thelma realizes that she was happier as her ordinary, sparkle-free self. So she ditches her horn, scrubs off her sparkles, and returns home, where her best friend is waiting for her with a hug.', NULL, NULL, 2.8632, 6.869, 0, 1.09, '2026-11-21 21:03:36', '2026-11-21 21:03:36')
