VALUES (9304, 'tt0117108', NULL, 'Multiplicity', 'Multiplicity', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/rlG2vi85uSEwWigVTtqDecVFTxR.jpg', 'https://image.tmdb.org/t/p/original/sihsl8L0G0RDIaKpQhNYQvIXJap.jpg', 'Construction worker Doug Kinney finds that the pressures of his working life, combined with his duties to his wife Laura and daughter Jennifer leaves him with little time for himself. However, he is approached by geneticist Dr. Owen Leeds, who offers Doug a rather unusual solution to his problems: cloning.', NULL, NULL, 2.7057, 5.829, 0, 1.02, '2026-11-21 21:03:36', '2026-11-21 21:03:36')
