VALUES (149789, 'tt0107531', NULL, 'Matusalem', 'Matusalem', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/4C7BpYX9leoHBwN9hBNsNaXEFtu.jpg', 'https://image.tmdb.org/t/p/original/fYoo1kgYTzNJeaiygVMmShstWoO.jpg', 'Fleeing from some other children who want to beat him, Olivier meets the ghost of a Pirate who every hundred years tries to find a parchment. Olivier agrees to help him. But in doing so he is captured by a bunch of pirates. The other children of the village discover a door thru time and space in an old haunted house and decide to rescue Olivier from Captain Monbars'' pirates.', NULL, NULL, 0.4945, 6.0, 0, 1.01, '2026-11-21 21:03:36', '2026-11-21 21:03:36')
