VALUES (38222, 'tt0066181', NULL, 'On a Clear Day You Can See Forever', 'On a Clear Day You Can See Forever', 'movie', 1970, 'https://image.tmdb.org/t/p/w500/maUgkAqcTTBpMbZoxUmuxtb9mzk.jpg', 'https://image.tmdb.org/t/p/original/3XKMnHWide4UiYg91P5dV073IVS.jpg', 'Daisy Gamble, an unusual woman who hears phones before they ring, and does wonders with her flowers, wants to quit smoking to please her fiancé, Warren. She goes to a doctor of hypnosis to do it. But once she''s under, her doctor finds out that she can regress into past lives and different personalities, and he finds himself falling in love with one of them.', NULL, NULL, 1.8151, 6.642, 0, 1.04, '2026-11-21 21:03:36', '2026-11-21 21:03:36')
