VALUES (49921, 'tt0059258', NULL, 'Catch Us If You Can', 'Catch Us If You Can', 'movie', 1965, 'https://image.tmdb.org/t/p/w500/b9uVoefbNxGemQyG0Aoh9xNU0LB.jpg', 'https://image.tmdb.org/t/p/original/gw0ugxqblFODyoQug4RLaD33FHe.jpg', 'Dinah is a famous model and actress who is getting tired of life in the limelight and wants to take a break. While shooting a commercial spot for meat, she meets Steve, a stuntman. Dinah and Steve hit it off and decide to head to an island to get away from it all, bringing along four of Steve''s friends. Before long, Dinah is reported missing and everyone is looking for her, making their getaway anything but tranquil.', NULL, NULL, 1.0102, 5.4, 0, 1.01, '2026-11-21 21:03:36', '2026-11-21 21:03:36')
