VALUES (14574, 'tt0914798', NULL, 'The Boy in the Striped Pyjamas', 'The Boy in the Striped Pyjamas', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/2C8QCXdMlojTxZjfBlINr4FWcb6.jpg', 'https://image.tmdb.org/t/p/original/6aRuABAdhuuDypLGscM7HoEWHx4.jpg', 'When his family moves from their home in Berlin to a strange new house in Poland, young Bruno befriends Shmuel, a boy who lives on the other side of the fence where everyone seems to be wearing striped pajamas. Unaware of Shmuel''s fate as a Jewish prisoner or the role his own Nazi father plays in his imprisonment, Bruno embarks on a dangerous journey inside the camp''s walls.', NULL, NULL, 10.6119, 7.817, 0, 12.68, '2026-07-15 12:01:52', '2026-11-21 21:03:36')
