VALUES (47665, 'tt2375692', NULL, 'Black Sails', 'Black Sails', 'tv', 2014, 'https://image.tmdb.org/t/p/w500/mZcSwrDdw6cdOVgXm496DgwrQcQ.jpg', 'https://image.tmdb.org/t/p/original/A7lo83g09i3cDmLRKtDiiYN8w0z.jpg', 'The pirate adventures of Captain Flint and his men twenty years prior to Robert Louis Stevenson’s classic “Treasure Island.” Flint, the most brilliant and most feared pirate captain of his day, takes on a fast-talking young addition to his crew who goes by the name John Silver. Threatened with extinction on all sides, they fight for the survival of New Providence Island, the most notorious criminal haven of its day – a debauched paradise teeming with pirates, prostitutes, thieves and fortune seekers, a place defined by both its enlightened ideals and its stunning brutality.', NULL, NULL, 27.7869, 7.6, 0, 2.19578947368421069e+01, '2026-07-15 12:01:52', '2026-11-21 21:03:36')
