VALUES (36685, 'tt0073629', NULL, 'The Rocky Horror Picture Show', 'The Rocky Horror Picture Show', 'movie', 1975, 'https://image.tmdb.org/t/p/w500/3pyE6ZqDbuJi7zrNzzQzcKTWdmN.jpg', 'https://image.tmdb.org/t/p/original/54aVU7tnvDKkX6ibzFg6ke03BV.jpg', 'After getting a flat tire in the middle of nowhere, newly engaged couple Brad and Janet encounter the eerie mansion of the flamboyant, seductive Dr Frank-N-Furter and a variety of eccentric characters. Through elaborate dance and rock music, the mad scientist unveils his latest creation: a perfect, muscular man.', NULL, NULL, 7.4206, 7.441, 0, 3.51048387096774234e+01, '2026-07-15 12:01:52', '2026-11-21 21:03:36')
