VALUES (404, 'tt0166896', NULL, 'The Straight Story', 'The Straight Story', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/tT9cMiVDdtlcdZxOoFy3VRmEoKk.jpg', 'https://image.tmdb.org/t/p/original/1S81PpyGwS8eVx4W75uSKzMw4B0.jpg', 'Retired farmer and widower Alvin Straight learns one day that his estranged brother Lyle has suffered a severe stroke. Alvin is determined to make things right with Lyle while he still can, but his brother lives in Wisconsin, while Alvin is stuck in Iowa with no car and no driver''s license. He then has the idea of making the trip on his old lawnmower, thus beginning a picturesque and at times deeply spiritual odyssey.', NULL, NULL, 4.1912, 7.738, 0, 3.3845172413793108e+01, '2026-07-20 04:02:06', '2026-11-21 21:03:36')
