VALUES (15043, 'tt0162212', NULL, 'Brink!', 'Brink!', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/hul7jmZJsBOjqKNZIEzxJPyemca.jpg', 'https://image.tmdb.org/t/p/original/4gpcNmMgF0leqkntewyi6lZJupS.jpg', 'Andy "Brink" Brinker and his in-line skating crew--Peter, Jordy, and Gabriella--who call themselves "Soul-Skaters" (which means they skate for the fun of it, and not for the money), clash with a group of sponsored skaters, Team X-Bladz--led by Val--with whom they attend high school in southern California. When Brink discovers his family is in financial trouble, he goes against the wishes of his parents and his friends and joins Team X-Bladz. Brink tries to lead a double life but will be able to pull it off?', NULL, NULL, 1.2861, 6.3, 0, 1.0198888888888888e+01, '2026-07-21 03:32:24', '2026-11-21 21:03:36')
