VALUES (223, 'tt0032976', NULL, 'Rebecca', 'Rebecca', 'movie', 1940, 'https://image.tmdb.org/t/p/w500/1qz3qUOHnVy7dL7M7G8jSErxE4b.jpg', 'https://image.tmdb.org/t/p/original/46p36NyMO6f25YtSqSYiwz4mKbW.jpg', 'Story of a young woman who marries a fascinating widower only to find out that she must live in the shadow of his former wife, Rebecca, who died mysteriously several years earlier. The young wife must come to grips with the terrible secret of her handsome, cold husband, Max De Winter. She must also deal with the jealous, obsessed Mrs. Danvers, the housekeeper, who will not accept her as the mistress of the house.', NULL, NULL, 5.0391, 7.881, 0, 3.44121212121212138e+01, '2026-07-30 18:28:39', '2026-11-21 21:03:36')
