VALUES (19120, 'tt0059229', NULL, 'Juliet of the Spirits', 'Giulietta degli spiriti', 'movie', 1965, 'https://image.tmdb.org/t/p/w500/NbN10moPWQiiIKDJsC7A3j4Mcy.jpg', 'https://image.tmdb.org/t/p/original/9VeXz4mj4QaOfTNSLy0owJHkWEo.jpg', 'Middle-aged Giulietta grows suspicious of her husband, Giorgio, when his behavior grows increasingly questionable. One night when Giorgio initiates a seance amongst his friends, Giulietta gets in touch with spirits and learns more about herself and her painful past. Slightly skeptical, but intrigued, she visits a mystic who gives her more information -- and nudges her toward the realization that her husband is indeed a philanderer.', NULL, NULL, 1.2849, 7.2, 0, 9.082, '2026-08-03 14:31:56', '2026-11-21 21:03:36')
