VALUES (63100, 'tt0063469', NULL, 'Psych-Out', 'Psych-Out', 'movie', 1968, 'https://image.tmdb.org/t/p/w500/gl0waHdQJkcP7TxjPl4V8jeduI4.jpg', 'https://image.tmdb.org/t/p/original/aM6IxzEuU4A5vUS2PbMYs90jNvS.jpg', 'Jenny, a deaf runaway who has just arrived in San Francisco''s Haight-Ashbury district to find her long-lost brother, a mysterious bearded sculptor known around town as The Seeker. She falls in with a psychedelic band, Mumblin'' Jim, whose members include Stoney, Ben, and Elwood. They hide her from the fuzz in their crash pad, a Victorian house crowded with love beads and necking couples. Mumblin'' Jim''s truth-seeking friend Dave considers the band''s pursuit of success "playing games," but he agrees to help Jennie anyway.', NULL, NULL, 1.1984, 4.9, 0, 2.01, '2026-08-17 16:08:12', '2026-11-21 21:03:36')
